arguments.query:
SELECT COUNT(*) AS cnt
FROM audit_logs
WHERE time BETWEEN '2022-07-16 14:58:54' AND '2022-07-16 15:08:54'
  AND (
    pname LIKE '%reg.exe%' OR process_name LIKE '%reg.exe%' OR command_line LIKE '%reg.exe%' OR object LIKE '%reg.exe%' OR childproc_name LIKE '%reg.exe%' OR parent_process_name LIKE '%reg.exe%' OR parent_process_path LIKE '%reg.exe%' OR parent_command_line LIKE '%reg.exe%'
  );

SELECT COUNT(*) AS row_count
FROM audit_logs
WHERE pid = 4872 AND ppid = 4424 AND (pname LIKE '%cmd.exe%' OR process_name LIKE '%cmd.exe%');

SELECT COUNT(*) AS direct_child_rows
FROM audit_logs
WHERE ppid = 4924;

SELECT COUNT(*) AS cnt, MIN(time) AS min_time, MAX(time) AS max_time, MIN(CAST(source_row_id AS INTEGER)) AS min_source_row_id, MAX(CAST(source_row_id AS INTEGER)) AS max_source_row_id
FROM audit_logs
WHERE command_line LIKE '%b37d3452-eb6b-46f2-a524-3d18188259b2%';

SELECT time,pid,ppid,pname,process_name,access,object,remote_ip,remote_port,command_line,parent_process_name,parent_process_path,parent_command_line,process_guid,parent_process_guid,source_stream,source_row_id,event_id,event_record_id,subject_user_name
FROM audit_logs
WHERE time BETWEEN '2022-07-16 15:04:13' AND '2022-07-16 15:04:22'
  AND (
    access LIKE '%CONNECTION%' OR access LIKE '%connect%' OR raw_event_type LIKE '%netconn%' OR remote_ip IS NOT NULL OR remote_port IS NOT NULL
  )
  AND (
    object LIKE '%127.0.0.1%' OR object LIKE '%51845%' OR remote_ip LIKE '%127.0.0.1%' OR remote_port LIKE '%51845%' OR command_line LIKE '%127.0.0.1%' OR command_line LIKE '%51845%'
  )
ORDER BY time, pid, ppid, source_stream, source_row_id, event_record_id;

